def objective(w):
    return (w - 3) ** 2

print(objective(0))   # 9: a bad (high) score

def objective(w):
    return (w - 3) ** 2

print(objective(2))   # 1: much better

def objective(w):
    return (w - 3) ** 2

candidates = [0.0, 2.0, 3.0, 5.0]
scores = {w: objective(w) for w in candidates}
best = min(scores, key=scores.get)
print(best)   # 3.0: the lowest objective
